import { GoogleGenAI } from "@google/genai";
import { RESUME_TEXT } from "../constants";

// Initialize the client only if the key exists, handled in the call to avoid init errors
const getAIClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    console.warn("Gemini API Key is missing.");
    return null;
  }
  return new GoogleGenAI({ apiKey });
};

export const sendMessageToGemini = async (userMessage: string): Promise<string> => {
  const ai = getAIClient();

  if (!ai) {
    return "I'm currently in demo mode as my API key hasn't been configured. I'd love to chat about Naman's experience once connected!";
  }

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: userMessage,
      config: {
        systemInstruction: `You are an AI assistant for Naman Mishra's portfolio website. 
        Your goal is to answer questions about Naman's professional experience, skills, and projects based STRICTLY on the following resume context.

        RESUME CONTEXT:
        ${RESUME_TEXT}

        Guidelines:
        1. Be professional, enthusiastic, and concise.
        2. Speak in the first person representing Naman (e.g., "I have experience with...") or as a helpful assistant (e.g., "Naman has experience with...").
        3. If a user asks about a skill not listed, say "It doesn't look like that's explicitly listed in the resume, but based on his backend expertise, he might be familiar with related concepts."
        4. Highlight the "Lead" aspect and "AI/RAG" expertise when relevant.
        `,
      }
    });

    return response.text || "I couldn't generate a response at the moment.";
  } catch (error) {
    console.error("Error communicating with Gemini:", error);
    return "Sorry, I encountered a temporary error connecting to my brain. Please try again later.";
  }
};

import React, { useState, useEffect } from 'react';
import { NAV_ITEMS } from '../constants';
import { Menu, X } from 'lucide-react';

const Navbar: React.FC = () => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <nav className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${isScrolled ? 'py-4' : 'py-6'}`}>
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className={`glass-card rounded-2xl px-6 py-3 flex items-center justify-between transition-all duration-300 ${isScrolled ? 'shadow-lg shadow-primary/10' : 'bg-transparent border-transparent backdrop-blur-none'}`}>

          <div className="flex items-center gap-2">
            <span className="text-2xl font-display font-bold bg-gradient-to-r from-primary to-secondary bg-clip-text text-transparent">
              NM
            </span>
          </div>

          {/* Desktop Nav */}
          <div className="hidden md:flex items-center gap-8">
            {NAV_ITEMS.map((item) => (
              <a
                key={item.label}
                href={item.href}
                className="text-sm font-medium text-slate-300 hover:text-white transition-colors flex items-center gap-2 group"
              >
                <item.icon className="w-4 h-4 group-hover:text-primary transition-colors" />
                {item.label}
              </a>
            ))}
            <a 
              href="#contact"
              className="bg-primary hover:bg-primary/90 text-white text-sm font-semibold px-5 py-2 rounded-full transition-all hover:shadow-[0_0_20px_rgba(14,165,233,0.5)]"
            >
              Contact Me
            </a>
          </div>

          {/* Mobile Menu Button */}
          <div className="md:hidden">
            <button 
              onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
              className="text-slate-300 hover:text-white"
            >
              {mobileMenuOpen ? <X /> : <Menu />}
            </button>
          </div>
        </div>
      </div>

      {/* Mobile Menu */}
      {mobileMenuOpen && (
        <div className="md:hidden absolute top-24 left-4 right-4 z-40">
           <div className="glass-card rounded-xl p-4 flex flex-col gap-4">
             {NAV_ITEMS.map((item) => (
              <a
                key={item.label}
                href={item.href}
                onClick={() => setMobileMenuOpen(false)}
                className="text-base font-medium text-slate-300 hover:text-white flex items-center gap-3 p-2 hover:bg-white/5 rounded-lg"
              >
                <item.icon className="w-5 h-5 text-primary" />
