            ))}
             <a 
              href="#contact"
              onClick={() => setMobileMenuOpen(false)}
              className="bg-primary text-center text-white font-semibold px-5 py-3 rounded-lg"
            >
              Contact Me
            </a>
           </div>
        </div>
      )}
    </nav>
  );
};

