const Experience: React.FC = () => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [scrollProgress, setScrollProgress] = useState(0);
  const [activeIndices, setActiveIndices] = useState<number[]>([]);

  useEffect(() => {
    const handleScroll = () => {
      if (!containerRef.current) return;

      const rect = containerRef.current.getBoundingClientRect();
      const windowHeight = window.innerHeight;

      // Trigger animation when the content is roughly in the middle of the screen
      const triggerPoint = windowHeight * 0.55; 

      // Calculate progress relative to container top
      const currentProgress = triggerPoint - rect.top;

      setScrollProgress(Math.max(0, currentProgress));

      // Determine active items based on scroll position
      const items = containerRef.current.querySelectorAll('.experience-item-marker');
      const newActiveIndices: number[] = [];

      items.forEach((item, index) => {
        const itemTop = (item as HTMLElement).offsetTop;
        // Add a small offset so the line passes the dot before it activates
        if (currentProgress > itemTop + 20) {
            newActiveIndices.push(index);
        }
      });

      // Only update if changed to avoid renders
      setActiveIndices(prev => {
        if (prev.length === newActiveIndices.length && prev.every((val, i) => val === newActiveIndices[i])) {
            return prev;
        }
        return newActiveIndices;
      });
    };

    window.addEventListener('scroll', handleScroll);
    handleScroll(); // Initial check
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <section id="experience" className="py-24 bg-dark relative">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="mb-20 text-center reveal-on-scroll">
           <span className="text-primary font-bold tracking-widest uppercase text-xs mb-2 block animate-pulse">8+ Years of Excellence</span>
          <h2 className="text-3xl md:text-5xl font-display font-bold">
            Professional <span className="text-gradient">Journey</span>
          </h2>
        </div>

        <div ref={containerRef} className="relative space-y-24">
          {/* Static Background Line */}
          <div className="absolute left-8 md:left-1/2 top-0 bottom-0 w-0.5 bg-slate-800 transform md:-translate-x-1/2 rounded-full"></div>

          {/* Animated Foreground Line */}
          <div 
            className="absolute left-8 md:left-1/2 top-0 w-0.5 bg-gradient-to-b from-primary via-secondary to-primary transform md:-translate-x-1/2 shadow-[0_0_15px_rgba(14,165,233,0.6)] rounded-full z-0"
            style={{ 
                height: `${scrollProgress}px`, 
                maxHeight: '100%',
                // Use a transition for smooth catch-up if scroll is jagged
                transition: 'height 0.1s linear' 
            }}
          >
             {/* Glowing tip at the bottom of the line */}
             <div className="absolute bottom-0 left-1/2 -translate-x-1/2 w-1.5 h-6 bg-white blur-[4px] rounded-full"></div>
          </div>

          {EXPERIENCE.map((exp, index) => (
             <div key={exp.id} className="experience-item-marker z-10 relative">
                 <ExperienceItem 
                    exp={exp} 
                    index={index} 
                    isActive={activeIndices.includes(index)} 
                 />
             </div>
          ))}
        </div>
      </div>
    </section>
  );
};

